package com.bocsoft.sqleditor.history.api;
import com.bocsoft.sqleditor.history.persistence.ExecutionHistoryRecord;
public class HistoryDetail extends HistorySummary {private final String statement,sqlState,errorMessage;private final Integer mysqlErrorCode;private final boolean connectionAvailable;public HistoryDetail(ExecutionHistoryRecord r,boolean available){super(r);statement=r.getStatementText();sqlState=r.getSqlState();errorMessage=r.getErrorMessage();mysqlErrorCode=r.getMysqlErrorCode();connectionAvailable=available;}public String getStatement(){return statement;}public String getSqlState(){return sqlState;}public String getErrorMessage(){return errorMessage;}public Integer getMysqlErrorCode(){return mysqlErrorCode;}public boolean isConnectionAvailable(){return connectionAvailable;}}
